import {
  collection,
  doc,
  setDoc,
  getDoc,
  getDocs,
  deleteDoc,
  serverTimestamp
} from 'firebase/firestore';
import { db, isFirebaseConfigured } from '../config/firebase';
import catalogData from '../data/catalog.json';

/**
 * =========================================================================
 * 1. PRODUCT CATALOG (bundled fallback for the Firestore catalog)
 * =========================================================================
 * src/data/catalog.json is generated by scripts/build_catalog.py from the
 * supplier CSVs in "product folder/" and pushed to Firestore by
 * scripts/seed-firestore.mjs. Firestore is the source of truth once seeded;
 * the bundled copy is used for the first paint and when Firestore is unreachable.
 */
export const CATALOG_VERSION = catalogData.version;
export const INITIAL_REAL_CATEGORIES = catalogData.categories;
export const INITIAL_REAL_PRODUCTS = catalogData.products;

const LOCAL_CACHE_KEYS = [
  'rubyred_db_products',
  'rubyred_db_categories',
  'rubyred_deleted_products',
  'rubyred_deleted_categories',
  'rubyred_catalog_remote_version'
];

// meta/catalog.version changes whenever an admin edits the catalog. Visitors
// read just that one document and reuse their cached catalog while it matches,
// instead of reading every product on every visit (Firestore read quota).
const REMOTE_VERSION_KEY = 'rubyred_catalog_remote_version';
const lastFetchWasRemote = {};

// Drop browser caches written by an older catalog (e.g. the previous demo products)
try {
  if (localStorage.getItem('rubyred_catalog_version') !== CATALOG_VERSION) {
    LOCAL_CACHE_KEYS.forEach(key => localStorage.removeItem(key));
    localStorage.setItem('rubyred_catalog_version', CATALOG_VERSION);
  }
} catch (e) {}

const bySortOrder = (a, b) => (a.sortOrder ?? 9999) - (b.sortOrder ?? 9999);

function sortProducts(products, categories) {
  const catOrder = new Map(categories.map((c, i) => [c.id, c.sortOrder ?? i]));
  return [...products].sort((a, b) =>
    (catOrder.get(a.categoryId) ?? 9999) - (catOrder.get(b.categoryId) ?? 9999) || bySortOrder(a, b)
  );
}

/**
 * Storefront catalog: categories + products, fetched once per page load and
 * shared by every component (see src/hooks/useCatalog.js).
 */
let catalogPromise = null;
const catalogListeners = new Set();

async function readRemoteCatalogVersion() {
  if (!isFirebaseConfigured || !db) return null;
  try {
    const snap = await getDoc(doc(db, 'meta', 'catalog'));
    return snap.exists() ? String(snap.data().version) : 'unversioned';
  } catch (err) {
    console.warn('[Catalog] version check failed:', err.message);
    return null;
  }
}

async function loadCatalog() {
  const remoteVersion = await readRemoteCatalogVersion();
  let cachedVersion = null;
  try {
    cachedVersion = localStorage.getItem(REMOTE_VERSION_KEY);
  } catch {
    /* storage unavailable */
  }
  const cachedCategories = readLocalList('rubyred_db_categories');
  const cachedProducts = readLocalList('rubyred_db_products');
  const hasCache = Boolean(cachedVersion) && cachedCategories.length > 0 && cachedProducts.length > 0;

  // Up to date (or Firestore unreachable): use this browser's copy
  if (hasCache && (remoteVersion === null || remoteVersion === cachedVersion)) {
    const categories = [...cachedCategories].sort(bySortOrder);
    return { categories, products: sortProducts(cachedProducts, categories) };
  }

  const [categories, products] = await Promise.all([fetchCategoriesFromDb(), fetchProductsFromDb()]);
  if (remoteVersion !== null && lastFetchWasRemote.categories && lastFetchWasRemote.products) {
    try {
      localStorage.setItem(REMOTE_VERSION_KEY, remoteVersion);
    } catch {
      /* storage unavailable */
    }
  }
  return { categories, products: sortProducts(products, categories) };
}

/** Marks the catalog as changed so every visitor re-downloads it once. */
async function bumpCatalogVersion() {
  if (!isFirebaseConfigured || !db) return;
  try {
    await setDoc(doc(db, 'meta', 'catalog'), { version: Date.now(), updatedAt: new Date().toISOString() });
  } catch (err) {
    console.warn('[Catalog] could not bump catalog version:', err.message);
  }
}

export function getCatalog() {
  if (!catalogPromise) {
    catalogPromise = loadCatalog()
      .catch(err => {
        console.warn('[Catalog] load failed, using bundled catalog:', err);
        catalogPromise = null;
        return { categories: INITIAL_REAL_CATEGORIES, products: INITIAL_REAL_PRODUCTS };
      });
  }
  return catalogPromise;
}

export function subscribeToCatalog(listener) {
  catalogListeners.add(listener);
  return () => catalogListeners.delete(listener);
}

function invalidateCatalog() {
  catalogPromise = null;
  if (catalogListeners.size > 0) {
    getCatalog().then(catalog => catalogListeners.forEach(fn => fn(catalog)));
  }
}


/**
 * =========================================================================
 * 2. FIRESTORE CATEGORIES CRUD
 * =========================================================================
 */
function readLocalList(key) {
  try {
    const raw = localStorage.getItem(key);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

function writeLocalList(key, list) {
  try {
    localStorage.setItem(key, JSON.stringify(list));
  } catch (e) {}
}

function upsertLocal(key, record, { prepend = false } = {}) {
  const list = readLocalList(key);
  const idx = list.findIndex(item => item.id === record.id);
  if (idx >= 0) list[idx] = record;
  else if (prepend) list.unshift(record);
  else list.push(record);
  writeLocalList(key, list);
}

function markLocallyDeleted(deletedKey, cacheKey, id) {
  const deleted = readLocalList(deletedKey);
  if (!deleted.includes(id)) writeLocalList(deletedKey, [...deleted, id]);
  writeLocalList(cacheKey, readLocalList(cacheKey).filter(item => item.id !== id));
}

/**
 * Reads a catalog collection. When Firestore answers with documents they are
 * the source of truth; otherwise the bundled catalog plus any edits saved in
 * this browser are used (offline / not-yet-seeded fallback).
 */
async function fetchCatalogCollection(collectionName, bundled, cacheKey, deletedKey) {
  let remote = null;
  if (isFirebaseConfigured && db) {
    try {
      const snap = await getDocs(collection(db, collectionName));
      if (!snap.empty) {
        remote = snap.docs.map(d => {
          const { timestamp: _timestamp, ...data } = d.data();
          return { ...data, id: d.id };
        });
      }
    } catch (err) {
      console.warn(`[Firestore] fetch ${collectionName} error:`, err.message);
    }
  }

  lastFetchWasRemote[collectionName] = Boolean(remote);

  let result;
  if (remote) {
    result = remote;
  } else {
    const deletedIds = readLocalList(deletedKey);
    const merged = new Map();
    bundled.forEach(item => merged.set(item.id, { ...item }));
    readLocalList(cacheKey).forEach(item => {
      if (item && item.id) merged.set(item.id, { ...(merged.get(item.id) || {}), ...item });
    });
    result = Array.from(merged.values()).filter(item => !deletedIds.includes(item.id));
  }

  result.sort(bySortOrder);
  writeLocalList(cacheKey, result);
  return result;
}

export async function fetchCategoriesFromDb() {
  return fetchCatalogCollection(
    'categories', INITIAL_REAL_CATEGORIES, 'rubyred_db_categories', 'rubyred_deleted_categories'
  );
}

export async function saveCategoryToDb(category) {
  const title = (category.title || category.name || '').trim();
  const catId = category.id || title.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');
  const image = category.img || category.image || '/images/cat_snacks.jpg';
  const record = {
    ...category,
    id: catId,
    name: title,
    title,
    img: image,
    image,
    updatedAt: new Date().toISOString()
  };

  upsertLocal('rubyred_db_categories', record);

  if (isFirebaseConfigured && db) {
    try {
      await setDoc(doc(db, 'categories', catId), { ...record, timestamp: serverTimestamp() });
      console.log('[Firestore DB] Saved category:', catId);
      await bumpCatalogVersion();
    } catch (err) {
      console.warn('[Firestore DB] Could not write category:', err.message);
    }
  }
  invalidateCatalog();
  return record;
}

export async function deleteCategoryFromDb(categoryId) {
  markLocallyDeleted('rubyred_deleted_categories', 'rubyred_db_categories', categoryId);

  if (isFirebaseConfigured && db) {
    try {
      await deleteDoc(doc(db, 'categories', categoryId));
      console.log('[Firestore DB] Deleted category:', categoryId);
      await bumpCatalogVersion();
    } catch (err) {
      console.warn('[Firestore DB] Delete category error:', err.message);
    }
  }
  invalidateCatalog();
  return true;
}

/**
 * =========================================================================
 * 3. FIRESTORE PRODUCTS CRUD
 * =========================================================================
 */
export async function fetchProductsFromDb() {
  return fetchCatalogCollection(
    'products', INITIAL_REAL_PRODUCTS, 'rubyred_db_products', 'rubyred_deleted_products'
  );
}

const toNumber = (value, fallback = 0) => {
  const n = parseFloat(value);
  return Number.isFinite(n) ? n : fallback;
};

const toInt = (value, fallback) => {
  const n = parseInt(value, 10);
  return Number.isFinite(n) ? n : fallback;
};

const cleanList = (list) =>
  Array.isArray(list) ? list.map(v => String(v).trim()).filter(Boolean) : [];

export async function saveProductToDb(product) {
  const prodId = product.id || `prod-${Date.now()}`;
  const title = (product.title || product.name || 'New Product').trim();
  const retailP = toNumber(product.retailPrice ?? product.price);
  const wholesaleP = toNumber(product.wholesalePrice ?? product.b2bPrice);
  const originalP = Math.max(toNumber(product.originalPrice, retailP), retailP);
  const desc = product.description || product.fullDesc || product.shortDesc || '';
  const brandVal = (product.brand || '').trim();
  const originVal = product.origin || '🌍 Imported';
  const netWeightVal = (product.netWeight || '').trim();
  const flavors = cleanList(product.flavors);
  const stock = toInt(product.stock ?? product.stockCount, 100);
  const image = product.img || product.image || '/images/ruby_red_hero.jpg';
  const gallery = cleanList(product.gallery);
  const fallbackCategory = INITIAL_REAL_CATEGORIES[0] || { id: 'snacks', title: 'Snacks' };

  const record = {
    ...product,
    id: prodId,
    title,
    name: title,
    sku: (product.sku || '').toString().trim(),
    barcode: (product.barcode || '').toString().trim(),
    unit: product.unit || 'ea.',
    categoryId: product.categoryId || fallbackCategory.id,
    categoryName: product.categoryName || fallbackCategory.title,
    brand: brandVal,
    origin: originVal,
    netWeight: netWeightVal,
    retailPrice: retailP,
    price: retailP,
    originalPrice: originalP,
    wholesalePrice: wholesaleP,
    b2bPrice: wholesaleP,
    caseQty: Math.max(toInt(product.caseQty, 1), 1),
    moq: Math.max(toInt(product.moq, 1), 1),
    stock,
    stockCount: stock,
    inStock: product.inStock !== false && stock > 0,
    featured: product.featured === true,
    img: image,
    image,
    gallery: gallery.length > 0 ? gallery : [image],
    description: desc,
    shortDesc: desc,
    fullDesc: desc,
    flavors,
    overview: {
      ...(product.overview || {}),
      origin: originVal,
      netWeight: netWeightVal,
      brand: brandVal,
      flavor: flavors[0] || product.overview?.flavor || '',
      shelfLife: product.overview?.shelfLife || '',
      storage: product.overview?.storage || 'Store in a cool, dry place away from direct sunlight'
    },
    bullets: cleanList(product.bullets),
    updatedAt: new Date().toISOString()
  };

  // Ratings are only kept when they come from real data
  if (product.rating == null || product.rating === '') delete record.rating;
  if (product.reviewsCount == null || product.reviewsCount === '') delete record.reviewsCount;

  upsertLocal('rubyred_db_products', record, { prepend: true });

  if (isFirebaseConfigured && db) {
    try {
      await setDoc(doc(db, 'products', prodId), { ...record, timestamp: serverTimestamp() });
      console.log('[Firestore DB] Saved product:', prodId);
      await bumpCatalogVersion();
    } catch (err) {
      console.warn('[Firestore DB] Could not write product:', err.message);
    }
  }
  invalidateCatalog();
  return record;
}

export async function deleteProductFromDb(productId) {
  markLocallyDeleted('rubyred_deleted_products', 'rubyred_db_products', productId);

  if (isFirebaseConfigured && db) {
    try {
      await deleteDoc(doc(db, 'products', productId));
      console.log('[Firestore DB] Deleted product:', productId);
      await bumpCatalogVersion();
    } catch (err) {
      console.warn('[Firestore DB] Delete product error:', err.message);
    }
  }
  invalidateCatalog();
  return true;
}

/**
 * =========================================================================
 * 6. LOCAL PROJECT DIRECTORY MEDIA UPLOAD (public/images/)
 * =========================================================================
 */
export async function uploadProjectMedia(file, customFilename = null) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const base64Data = reader.result;
        const filename = customFilename || file.name || `media_${Date.now()}.png`;
        
        const response = await fetch('/api/media/upload', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ filename, base64Data })
        });
        
        const resJson = await response.json();
        if (resJson.success) {
          console.log('[Project Media] Saved to public/images/:', resJson.file.url);
          resolve(resJson.file);
        } else {
          resolve({ name: filename, url: base64Data });
        }
      } catch (e) {
        console.warn('[Project Media] Saved locally as Data URL:', e.message);
        resolve({ name: file.name, url: reader.result });
      }
    };
    reader.onerror = err => reject(err);
    reader.readAsDataURL(file);
  });
}
